  position: relative;
}
.loader12::after, .loader12::before {
  content: "";
  width: 48px;
  height: 48px;
  border: 2px solid var(--adminuiux-theme-accent-1);
  position: absolute;
  left: 0;
  top: 0;
  box-sizing: border-box;
  animation: loader12anim1 2s ease-in-out infinite;
}
.loader12::after {
