  width: 48px;
  height: 48px;
  background: var(--adminuiux-theme-1);
  transform: rotateX(65deg) rotate(45deg);
  color: var(--adminuiux-theme-accent-1);
  animation: loader13anim1 1s linear infinite alternate;
}
.loader13:after {
  content: "";
  position: absolute;
  inset: 0;
